import java.awt.Point;
import java.util.ArrayList;
import java.util.List;
import javax.swing.JLabel;
import javax.swing.JPanel;

/**
 * TASK: Record every mouse click on a panel.
 *
 * ClickTracker is a JPanel holding one JLabel (already named "count").
 * In the constructor, register a MouseListener so that each CLICK:
 *   1. appends a new Point(e.getX(), e.getY()) to the clicks list, and
 *   2. updates the label text to "Clicks: " + the number of clicks so far.
 *
 * MouseListener has five methods; extending java.awt.event.MouseAdapter and
 * overriding only mouseClicked keeps the code short.
 *
 * Example:
 *   ClickTracker t = new ClickTracker();
 *   // after a click at x=10, y=20
 *   t.getClicks().size()      -> 1
 *   t.getClicks().get(0).x    -> 10
 *   label text                -> "Clicks: 1"
 *
 * No window is ever opened -- the tests build MouseEvents by hand and hand them
 * to the panel with dispatchEvent.
 */
public class ClickTracker extends JPanel {

    private final List<Point> clicks = new ArrayList<>();
    private final JLabel countLabel = new JLabel("Clicks: 0");

    public ClickTracker() {
        countLabel.setName("count");
        add(countLabel);
        // TODO: addMouseListener(...) so mouseClicked records the point and
        // sets countLabel's text to "Clicks: " + clicks.size()
    }

    public List<Point> getClicks() {
        return clicks;
    }
}

