import java.awt.Component;
import java.awt.Container;
import java.awt.Point;
import java.awt.event.MouseEvent;
import java.util.List;
import javax.swing.JLabel;

public class ClickTrackerTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static Component find(Container root, String name) {
        for (Component c : root.getComponents()) {
            if (name.equals(c.getName())) {
                return c;
            }
            if (c instanceof Container) {
                Component found = find((Container) c, name);
                if (found != null) {
                    return found;
                }
            }
        }
        return null;
    }

    static String labelText(ClickTracker panel) {
        Component c = find(panel, "count");
        return c instanceof JLabel ? ((JLabel) c).getText() : null;
    }

    static void click(ClickTracker panel, int x, int y) {
        panel.dispatchEvent(new MouseEvent(panel, MouseEvent.MOUSE_CLICKED,
                System.currentTimeMillis(), 0, x, y, 1, false));
    }

    static Integer size(List<Point> points) {
        return points == null ? null : Integer.valueOf(points.size());
    }

    public static void main(String[] args) {
        try {
            ClickTracker panel = new ClickTracker();
            check("a MouseListener is registered", true, panel.getMouseListeners().length >= 1);
            check("no clicks yet", 0, size(panel.getClicks()));
            check("label starts at zero", "Clicks: 0", labelText(panel));

            click(panel, 10, 20);
            check("one click recorded", 1, size(panel.getClicks()));

            List<Point> clicks = panel.getClicks();
            Point first = clicks == null || clicks.isEmpty() ? null : clicks.get(0);
            check("first click x", 10, first == null ? null : Integer.valueOf(first.x));
            check("first click y", 20, first == null ? null : Integer.valueOf(first.y));

            click(panel, 30, 40);
            click(panel, 7, 8);
            check("label after three clicks", "Clicks: 3", labelText(panel));

            StringBuilder xs = new StringBuilder();
            if (panel.getClicks() != null) {
                for (Point p : panel.getClicks()) {
                    xs.append(p.x).append(" ");
                }
            }
            check("clicks kept in order", "10 30 7 ", xs.toString());
        } catch (Throwable t) {
            System.out.println("FAIL  unexpected " + t.getClass().getSimpleName() + ": " + t.getMessage());
            failures++;
        }

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

