import java.awt.Point;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.ArrayList;
import java.util.List;
import javax.swing.JLabel;
import javax.swing.JPanel;

public class ClickTracker extends JPanel {

    private final List<Point> clicks = new ArrayList<>();
    private final JLabel countLabel = new JLabel("Clicks: 0");

    public ClickTracker() {
        countLabel.setName("count");
        add(countLabel);
        addMouseListener(new MouseAdapter() {
            @Override
            public void mouseClicked(MouseEvent e) {
                clicks.add(new Point(e.getX(), e.getY()));
                countLabel.setText("Clicks: " + clicks.size());
            }
        });
    }

    public List<Point> getClicks() {
        return clicks;
    }
}
